mapper.select:
SELECT apr30_appr_step_group_id AS appr_step_group_id,
       apr30_appr_step_group_nm AS appr_step_group_name,
       apr30_note               AS note
  FROM apr30_appr_step_group
 WHERE apr30_appr_step_group_id = #{apprStepGroupId}
   AND apr30_company_id = #{companyId}

mapper.update:
UPDATE apr30_appr_step_group
   SET apr30_appr_step_group_nm = #{req.apprStepGroupName},
       apr30_note               = #{req.note}
 WHERE apr30_appr_step_group_id = #{req.apprStepGroupId}
   AND apr30_company_id = #{companyId}

mapper.delete:
DELETE FROM apr30_appr_step_group
 WHERE apr30_appr_step_group_id = #{apprStepGroupId}
   AND apr30_company_id = #{companyId}
